"""Build, merge, load and save the ai-register.yaml inventory.

The register is meant to be edited by people. A scan fills in what it can see
in the code; owners, purposes, reviewed tiers and control evidence are typed in
by people and are kept when the register is regenerated.
"""

from __future__ import annotations

from datetime import UTC, datetime
from pathlib import Path

import yaml

from . import __version__
from .controls import checklist
from .risk import assess
from .scanner import System

REGISTER_VERSION = 1
DRAFT_NOTICE = (
    "DRAFT. Generated by keyword scanning. Risk tiers and controls are suggestions "
    "for a human reviewer, not legal or compliance advice."
)
HUMAN_SYSTEM_FIELDS = ("owner", "purpose", "review_status")
HUMAN_RISK_FIELDS = ("reviewed_tier", "reviewer_notes")
HUMAN_CONTROL_FIELDS = ("status", "evidence")


def system_entry(system: System, previous: dict | None = None) -> dict:
    previous = previous or {}
    purpose = previous.get("purpose")
    result = assess(system.text_sample, purpose)
    old_risk = previous.get("risk") or {}
    old_controls = {c["id"]: c for c in previous.get("controls") or [] if "id" in c}
    controls = checklist(system, old_risk.get("reviewed_tier") or result.tier)
    for control in controls:
        old = old_controls.get(control["id"], {})
        for key in HUMAN_CONTROL_FIELDS:
            if old.get(key) is not None:
                control[key] = old[key]
    entry = {
        "id": system.id,
        "name": previous.get("name") or system.name,
        "lifecycle": "active",
        "owner": previous.get("owner"),
        "purpose": purpose,
        "review_status": previous.get("review_status") or "draft",
        "providers": system.providers,
        "models": system.models,
        "vector_stores": system.vector_stores,
        "mcp_servers": system.mcp_servers,
        "data_hints": system.hints,
        "risk": {
            "draft_tier": result.tier,
            "reasoning": result.reasoning,
            "reviewed_tier": old_risk.get("reviewed_tier"),
            "reviewer_notes": old_risk.get("reviewer_notes"),
        },
        "controls": controls,
        "findings": [f.to_dict() for f in system.findings],
    }
    return entry


def build(systems: list[System], scan_root: str, previous: dict | None = None, now: datetime | None = None) -> dict:
    """Create a register, carrying human-entered fields over from `previous`."""
    old_systems = {s["id"]: s for s in (previous or {}).get("systems", []) if "id" in s}
    entries = [system_entry(s, old_systems.get(s.id)) for s in systems]
    current = {s.id for s in systems}
    for old_id, old in old_systems.items():
        if old_id in current:
            continue
        retired = dict(old)
        retired["lifecycle"] = "not-detected"
        entries.append(retired)
    entries.sort(key=lambda e: e["id"])
    stamp = (now or datetime.now(UTC)).replace(microsecond=0).isoformat()
    return {
        "register_version": REGISTER_VERSION,
        "notice": DRAFT_NOTICE,
        "generated_by": f"ai-register {__version__}",
        "generated_at": stamp,
        "scan_root": scan_root,
        "systems": entries,
    }


def load(path: Path) -> dict:
    data = yaml.safe_load(path.read_text("utf-8")) or {}
    if not isinstance(data, dict) or "systems" not in data:
        raise ValueError(f"{path} is not an ai-register file (no 'systems' key)")
    if data.get("register_version", REGISTER_VERSION) > REGISTER_VERSION:
        raise ValueError(f"{path} was written by a newer ai-register")
    return data


def dump(register: dict) -> str:
    return yaml.safe_dump(register, sort_keys=False, allow_unicode=True, width=100)


def save(register: dict, path: Path) -> None:
    path.write_text(dump(register), "utf-8")


def effective_tier(entry: dict) -> str:
    risk = entry.get("risk") or {}
    return risk.get("reviewed_tier") or risk.get("draft_tier") or "minimal-risk"
